// 各字面標頭檔用它在編譯期比對自己那份與共用這份：逐筆相同才編得過。
template <size_t N, size_t M>
constexpr bool ubuntuUiIntervalsEqual(const EpdUnicodeInterval (&a)[N], const EpdUnicodeInterval (&b)[M]) {
  if (N != M) return false;
  for (size_t i = 0; i < N; i++) {
    if (a[i].first != b[i].first || a[i].last != b[i].last || a[i].offset != b[i].offset) return false;
  }
  return true;
}
